package com.taskflow.userservice.exception;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.ConstraintViolationException; import org.slf4j.*; import org.springframework.dao.DataAccessException; import org.springframework.http.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class);
record ErrorResponse(Instant timestamp,int status,String error,String message,Map<String,String> validationErrors,String path) {}
private ErrorResponse body(HttpStatus s,String m,Map<String,String> v,HttpServletRequest r){return new ErrorResponse(Instant.now(),s.value(),s.getReasonPhrase(),m,v,r.getRequestURI());}
@ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ErrorResponse> missing(RuntimeException e,HttpServletRequest r){return ResponseEntity.status(404).body(body(HttpStatus.NOT_FOUND,e.getMessage(),Map.of(),r));}
@ExceptionHandler(DuplicateEmailException.class) ResponseEntity<ErrorResponse> duplicate(RuntimeException e,HttpServletRequest r){return ResponseEntity.status(409).body(body(HttpStatus.CONFLICT,e.getMessage(),Map.of(),r));}
@ExceptionHandler(InvalidTaskException.class) ResponseEntity<ErrorResponse> invalidTask(RuntimeException e,HttpServletRequest r){return ResponseEntity.badRequest().body(body(HttpStatus.BAD_REQUEST,e.getMessage(),Map.of(),r));}
@ExceptionHandler(org.springframework.security.authentication.BadCredentialsException.class) ResponseEntity<ErrorResponse> badCredentials(Exception e,HttpServletRequest r){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(body(HttpStatus.UNAUTHORIZED,"Invalid email or password",Map.of(),r));}
@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){Map<String,String> errors=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->errors.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(body(HttpStatus.BAD_REQUEST,"Validation failed",errors,r));}
@ExceptionHandler({ConstraintViolationException.class,HttpMessageNotReadableException.class,IllegalArgumentException.class}) ResponseEntity<ErrorResponse> badRequest(Exception e,HttpServletRequest r){return ResponseEntity.badRequest().body(body(HttpStatus.BAD_REQUEST,"Invalid request",Map.of(),r));}
@ExceptionHandler(DataAccessException.class) ResponseEntity<ErrorResponse> database(DataAccessException e,HttpServletRequest r){log.error("Database operation failed",e);return ResponseEntity.status(500).body(body(HttpStatus.INTERNAL_SERVER_ERROR,"Database operation failed",Map.of(),r));}
@ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> unexpected(Exception e,HttpServletRequest r){log.error("Unhandled request error",e);return ResponseEntity.status(500).body(body(HttpStatus.INTERNAL_SERVER_ERROR,"Unexpected server error",Map.of(),r));} }
